class MiniCPMV4_5VideoProcessorKwargs(VideosKwargs, total=False):
    r"""
    max_num_frames (`int`, *optional*, defaults to 180):
        Frame budget per video: longer videos are packed into groups of consecutive frames, and up to
        `max_num_frames * max_num_packing` frames are sampled.
    max_num_packing (`int`, *optional*, defaults to 3):
        Maximum number of consecutive frames packed into one group, which the resampler turns into one set of tokens.
    max_slice_nums (`int`, *optional*, defaults to 1):
        Maximum number of slices each frame is split into.
    scale_resolution (`int`, *optional*, defaults to 448):
        Target resolution for individual slices.
    patch_size (`int`, *optional*, defaults to 14):
        Spatial patch size of the vision encoder.
    slice_mode (`bool`, *optional*, defaults to `True`):
        Whether to split frames into multiple slices for higher resolution.
    """

    max_num_frames: int
    max_num_packing: int
    max_slice_nums: int
    scale_resolution: int
    patch_size: int
    slice_mode: bool


def ensure_divide(length: int, divisor: int) -> int:
    return max(round(length / divisor) * divisor, divisor)


def find_best_resize(
    image_size: tuple[float, float], scale_resolution: int, patch_size: int, allow_upscale: bool = False
) -> tuple[int, int]:
    """
    Resize `(height, width)` to roughly `scale_resolution**2` pixels (only when larger, unless `allow_upscale`), keeping
    the aspect ratio, then round each side to a multiple of `patch_size`.
    """
    height, width = image_size
    if (height * width > scale_resolution * scale_resolution) or allow_upscale:
        aspect_ratio = width / height
        height = int(scale_resolution / math.sqrt(aspect_ratio))
        width = int(height * aspect_ratio)
    return ensure_divide(height, patch_size), ensure_divide(width, patch_size)


@auto_docstring
class MiniCPMV4_5VideoProcessor(BaseVideoProcessor):
    resample = PILImageResampling.BICUBIC
    do_resize = True
    do_rescale = True
    do_normalize = True
    image_mean = IMAGENET_STANDARD_MEAN
    image_std = IMAGENET_STANDARD_STD
    do_convert_rgb = True
    # Frames are sliced like MiniCPM-V 2.5 images (sizes rounded to the patch size); groups of consecutive frames are
    # packed so that the resampler compresses each group, with each frame's timestamp, into one set of tokens.
    max_slice_nums = 1
    scale_resolution = 448
    patch_size = 14
    slice_mode = True
    do_sample_frames = True
    max_num_frames = 180
    valid_kwargs = MiniCPMV4_5VideoProcessorKwargs
    model_input_names = [
        "pixel_values_videos",
        "pixel_attention_mask_videos",
        "patch_position_ids_videos",
        "temporal_ids",
    ]
    fps = 5
    max_num_packing = 3
    time_scale = 0.1

    def __init__(self, **kwargs: Unpack[MiniCPMV4_5VideoProcessorKwargs]):
        super().__init__(**kwargs)

    def _validate_preprocess_kwargs(self, **kwargs):
        # Drop `do_resize`, model resizes based on auto-inferred size at run-time
        kwargs.pop("do_resize")
        super()._validate_preprocess_kwargs(**kwargs)

    def sample_frames(
        self,
        metadata: VideoMetadata,
        num_frames: int | None = None,
        fps: float | None = None,
        max_num_frames: int | None = None,
        max_num_packing: int | None = None,
        **kwargs,
    ):
        """
        Args:
            metadata (`VideoMetadata`):
                Metadata of the video containing information about total duration, fps and total number of frames.
            num_frames (`int`, *optional*):
                Number of frames to sample uniformly, instead of sampling at `fps`.
            fps (`float`, *optional*):
                Frames per second to sample.
            max_num_frames (`int`, *optional*):
                Frame budget; longer videos are packed, and up to `max_num_frames * max_num_packing` frames are sampled.
            max_num_packing (`int`, *optional*):
                Maximum number of frames packed into one group.
        Returns:
            list[int]: Indices to sample video frames.
        """
        if metadata is None or metadata.duration is None or metadata.fps is None:
            raise ValueError(
                "MiniCPMV4_5 requires video metadata with `duration` and `fps` to sample frames. "
                "Please pass a complete `VideoMetadata` object or set `do_sample_frames=False`."
            )
        fps = fps if fps is not None else self.fps
        max_num_frames = max_num_frames if max_num_frames is not None else self.max_num_frames
        max_num_packing = max_num_packing if max_num_packing is not None else self.max_num_packing

        if num_frames is None:
            if fps * int(metadata.duration) <= max_num_frames:
                num_frames = round(min(fps, round(metadata.fps)) * min(max_num_frames, metadata.duration))
            else:
                num_frames = round(min(metadata.duration * fps, max_num_frames * max_num_packing))
        gap = metadata.total_num_frames / num_frames
        return [int(i * gap + gap / 2) for i in range(num_frames)]

    def find_best_resize(
        self, video_size, scale_resolution, patch_size, allow_upscale=False, **kwargs
    ) -> tuple[int, int]:
        return find_best_resize(video_size, scale_resolution, patch_size, allow_upscale)

    def get_refine_size(
        self,
        video_size: tuple[int, int],
        grid: list[int],
        scale_resolution: int,
        patch_size: int,
        allow_upscale: bool = False,
        downsample_mode: str = "16x",
    ) -> tuple[int, int]:
        height, width = video_size
        grid_y, grid_x = grid
        refine_width = ensure_divide(width, grid_x)
        refine_height = ensure_divide(height, grid_y)

        best_height, best_width = self.find_best_resize(
            video_size=(refine_height / grid_y, refine_width / grid_x),
            scale_resolution=scale_resolution,
            patch_size=patch_size,
            downsample_mode=downsample_mode,
            allow_upscale=allow_upscale,
        )
        return best_height * grid_y, best_width * grid_x

    def get_sliced_grid(
        self,
        video_size: tuple[int, int],
        max_slice_nums: int,
        scale_resolution: int,
    ) -> list[int] | None:
        original_height, original_width = video_size
        log_ratio = math.log(original_width / original_height)
        ratio = original_width * original_height / (scale_resolution * scale_resolution)
        multiple = min(math.ceil(ratio), max_slice_nums)
        if multiple <= 1:
            return None

        best_grid = [1, 1]
        min_error = float("inf")
        for num_slices in [multiple - 1, multiple, multiple + 1]:
            if num_slices == 1 or num_slices > max_slice_nums:
                continue
            for num_rows in range(1, num_slices + 1):
                if num_slices % num_rows == 0:
                    num_cols = num_slices // num_rows
                    error = abs(log_ratio - math.log(num_cols / num_rows))
                    if error < min_error:
                        best_grid = [num_rows, num_cols]
                        min_error = error
                    elif error == min_error and num_rows > best_grid[0]:
                        best_grid = [num_rows, num_cols]
        return best_grid

    def reshape_by_patch(self, videos: "torch.Tensor", patch_size: int) -> "torch.Tensor":
        "Reshape ``[B, T, C, H, W]`` into NaViT patchified format ``[B, T, C, patch_size, H*W/patch_size]``."
        batch, time, num_channels, height, width = videos.shape

        # merge B and T so unfold sees 4D (B*T, C, H, W)
        videos = videos.reshape(batch * time, num_channels, height, width)
        patches = torch.nn.functional.unfold(videos, (patch_size, patch_size), stride=(patch_size, patch_size))

        patches = patches.reshape(batch, time, num_channels, patch_size, patch_size, -1)
        patches = patches.permute(0, 1, 2, 3, 5, 4)  # (B, T, C, patch_size, num_patches, patch_size)
        patches = patches.reshape(batch, time, num_channels, patch_size, -1)  # (B, T, C, patch_size, H*W/patch_size)

        return patches

    @auto_docstring
    def preprocess(
        self,
        videos: VideoInput,
        **kwargs: Unpack[VideosKwargs],
    ) -> BatchFeature:
        validate_kwargs(
            captured_kwargs=kwargs.keys(),
            valid_processor_keys=list(self.valid_kwargs.__annotations__.keys()) + ["return_tensors"],
        )

        # Perform type validation on received kwargs
        validate_typed_dict(self.valid_kwargs, kwargs)

        # Set default kwargs from self. This ensures that if a kwarg is not provided
        # by the user, it gets its default value from the instance, or is set to None.
        for kwarg_name in self.valid_kwargs.__annotations__:
            kwargs.setdefault(kwarg_name, getattr(self, kwarg_name, None))

        input_data_format = kwargs.pop("input_data_format")
        do_sample_frames = kwargs.pop("do_sample_frames")
        device = kwargs.pop("device")
        video_metadata = kwargs.pop("video_metadata")

        sample_indices_fn = partial(self.sample_frames, **kwargs) if do_sample_frames else None
        videos, video_metadata = self._decode_and_sample_videos(
            videos,
            video_metadata=video_metadata,
            do_sample_frames=do_sample_frames,
            sample_indices_fn=sample_indices_fn,
        )
        videos = self._prepare_input_videos(
            videos=videos,
            input_data_format=input_data_format,
            device=device,
        )

        kwargs = self._standardize_kwargs(**kwargs)
        self._validate_preprocess_kwargs(**kwargs)

        # Pop kwargs that are not needed in _preprocess
        kwargs.pop("data_format")
        return_metadata = kwargs.pop("return_metadata")

        # Diff from base class, pass on `video_metadata` to infer subframes vs main frames
        preprocessed_videos = self._preprocess(videos=videos, video_metadata=video_metadata, **kwargs)
        if return_metadata:
            preprocessed_videos["video_metadata"] = video_metadata
        return preprocessed_videos

    def resize_and_split_patches(
        self,
        video: "torch.Tensor",
        resample,
        slice_mode: bool,
        max_slice_nums: int,
        scale_resolution: int,
        patch_size: int,
        downsample_mode: str = "16x",
    ):
        num_frames = video.shape[1]
        video_size = video.shape[-2:]
        best_grid = None

        if slice_mode:
            best_grid = self.get_sliced_grid(video_size, max_slice_nums, scale_resolution)

        # Always resize the source
        new_height, new_width = self.find_best_resize(
            video_size,
            scale_resolution,
            patch_size,
            downsample_mode=downsample_mode,
            allow_upscale=(best_grid is None),
        )
        source_videos = self.resize(video, size=SizeDict(height=new_height, width=new_width), resample=resample)

        # Collect all patches: [source, *slices]
        patches = [source_videos]
        if best_grid is not None:
            refine_height, refine_width = self.get_refine_size(
                video_size,
                best_grid,
                scale_resolution,
                patch_size,
                downsample_mode=downsample_mode,
                allow_upscale=True,
            )
            grid_y, grid_x = best_grid
            patch_height, patch_width = refine_height // grid_y, refine_width // grid_x

            refine_videos = self.resize(
                video, size=SizeDict(height=refine_height, width=refine_width), resample=resample
            )
            refine_videos = divide_to_patches(refine_videos, (patch_height, patch_width))
            patches.extend(refine_videos)

        # Reorder from `all_sources+all_patches` to represent each video as `source+patch`
        patches_grouped_by_batch = [
            [patches[patch][batch] for patch in range(len(patches))] for batch in range(len(video))
        ]

        # MiniCPM needs to process each video as a single frame instead of processing all together
        # So each video is represented as `source-frame, patch-frame, patch-frame, [...], source-frame, patch-frame, [...]`
        interleaved_frames = []
        for sublist in patches_grouped_by_batch:
            # Split all tensors into frames: each becomes T x (1, 3, H, W)
            all_frames = [patch.unsqueeze(1).unbind(0) for patch in sublist]
            # Interleave: for each timestep, yield source then all patch frames
            interleaved_frames.append([frame for t in zip(*all_frames) for frame in t])

        grid = best_grid if best_grid is not None else (0, 0)
        num_patches = (grid[0] * grid[1]) + 1
        # Expand by batch size per each video
        num_patches = [[num_patches] * num_frames] * len(video)
        grids = [[grid] * num_frames] * len(video)
        return interleaved_frames, grids, num_patches

    def _preprocess(
        self,
        videos: list[torch.Tensor],
        do_resize: bool,
        resample,
        do_rescale: bool,
        rescale_factor: float,
        do_normalize: bool,
        image_mean: float | list[float] | None,
        image_std: float | list[float] | None,
        max_slice_nums: int,
        scale_resolution: int,
        patch_size: int,
        slice_mode: bool,
        max_num_frames: int,
        max_num_packing: int,
        video_metadata: list[VideoMetadata],
        fps: float,
        return_tensors: str | TensorType | None = None,
        **kwargs,
    ) -> BatchFeature:
        slices, temporal_ids, grids, num_groups = [], [], [], []
        for video, metadata in zip(videos, video_metadata):
            # Timestamps on the original 0.1 s grid (frames without metadata are taken as sampled at `fps`),
            # then groups of consecutive frames
            video_fps = metadata.fps or fps
            duration = metadata.duration or metadata.total_num_frames / video_fps
            timestamps = np.asarray(metadata.frames_indices) / video_fps
            scale = np.arange(0, duration, self.time_scale)
            frame_ids = (scale[np.abs(scale[None, :] - timestamps[:, None]).argmin(-1)] / self.time_scale).astype(
                np.int32
            )
            num_packing = self.get_num_packing(duration, fps, max_num_frames, max_num_packing)

            if do_resize:
                frames, frame_grids, _ = self.resize_and_split_patches(
                    video[None], resample, slice_mode, max_slice_nums, scale_resolution, patch_size
                )
                # num_frames * (overview + slices), frame-major
                frames, grid = [frame[0] for frame in frames[0]], frame_grids[0][0]
            else:
                frames, grid = list(video), (0, 0)
            num_slices = grid[0] * grid[1] + 1
            grouped, grouped_index = group_images_by_shape(frames, disable_grouping=False)
            processed = {
                shape: self.rescale_and_normalize(
                    stacked.float(), do_rescale, rescale_factor, do_normalize, image_mean, image_std
                )
                for shape, stacked in grouped.items()
            }
            frames = reorder_images(processed, grouped_index)

            # Group-major order: for each group, each slice index, the group's frames
            for start in range(0, len(frame_ids), num_packing):
                group_ids = frame_ids[start : start + num_packing].tolist()
                for slice_idx in range(num_slices):
                    for frame_idx in range(start, start + len(group_ids)):
                        slices.append(frames[frame_idx * num_slices + slice_idx])
                    temporal_ids.append(group_ids)
            grids.append(list(grid))
            num_groups.append(math.ceil(len(frame_ids) / num_packing))

        # One row of patches per frame slice, padded to the longest, as for images
        sizes = [(s.shape[-2] // patch_size, s.shape[-1] // patch_size) for s in slices]
        rows = [self.reshape_by_patch(s[None, None], patch_size)[0, 0] for s in slices]
        num_patches = [height * width for height, width in sizes]
        max_patches = max(num_patches)
        device = slices[0].device
        pixel_values = torch.stack([F.pad(r, (0, (max_patches - n) * patch_size)) for r, n in zip(rows, num_patches)])
        patch_index = torch.arange(max_patches, device=device)[None, :]
        pixel_attention_mask = patch_index < torch.tensor(num_patches, device=device)[:, None]
        widths = torch.tensor([width for _, width in sizes], device=device)[:, None]
        patch_position_ids = torch.stack([patch_index // widths, patch_index % widths], dim=-1)
        max_frames = max(len(ids) for ids in temporal_ids)
        temporal_ids = torch.tensor([ids + [-1] * (max_frames - len(ids)) for ids in temporal_ids])
        return BatchFeature(
            data={
                "pixel_values_videos": pixel_values,
                "pixel_attention_mask_videos": pixel_attention_mask,
                "patch_position_ids_videos": patch_position_ids * pixel_attention_mask[..., None],
                "temporal_ids": temporal_ids,
                "grids_videos": grids,
                "num_groups_per_video": num_groups,
            },
            tensor_type=return_tensors,
            skip_tensor_conversion=["grids_videos", "num_groups_per_video"],
        )

    def get_num_packing(self, duration: float, fps: float, max_num_frames: int, max_num_packing: int) -> int:
        """Number of consecutive frames packed into one group, as chosen by the original `encode_video`."""
        if fps * int(duration) <= max_num_frames:
            return 1
        return min(math.ceil(duration * fps / max_num_frames), max_num_packing)


